parameters.text:
=Request envelope:
{{ JSON.stringify($json.body || $json) }}

Return ONLY valid JSON with this shape:
{
  "answer": "short user-facing answer candidate",
  "route_decision": {
    "decision": "answer_direct|retrieve_knowledge|ingest_or_stage_knowledge|activate_skill|create_skill|request_human_clarification",
    "target_agent": "actor_twin|knowledge_fabric_agent|agentic_butler|human",
    "intent": "answer_question|retrieve_context|ingest_concept|activate_skill|create_skill|clarify",
    "visible_state": "answering|using_knowledge|capturing_knowledge|activating_skill|approval_required",
    "approval_required": false,
    "handoff_required": false,
    "reason": "why this route was selected"
  }
}

parameters.jsCode:
const inputRoot = $('Receive request').first().json;
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || 'req_' + executionId;
const aiText = ai.output || ai.text || ai.response || ai.message || '';

function safeJson(value) {
  if (value && typeof value === 'object') return value;
  const text = String(value || '').trim();
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced ? fenced[1] : text).trim();
  const firstBrace = candidate.indexOf('{');
  const lastBrace = candidate.lastIndexOf('}');
  if (firstBrace < 0 || lastBrace <= firstBrace) return null;
  try { return JSON.parse(candidate.slice(firstBrace, lastBrace + 1)); } catch { return null; }
}

function normalizeDecision(raw) {
  if (typeof raw === 'string') return { decision: raw };
  if (raw && typeof raw === 'object') return raw;
  return {};
}

function identityIntent(inputValue) {
  const text = JSON.stringify(inputValue?.input || inputValue || {}).toLowerCase();
  return /\b(who are you|what are you|what is your purpose|what's your purpose|describe yourself|introduce yourself)\b/i.test(text);
}

function inferDecision(inputValue, embedded) {
  if (identityIntent(inputValue)) return 'answer_direct';
  const query = JSON.stringify(inputValue?.input || inputValue || {}).toLowerCase();
  const embeddedText = JSON.stringify(embedded || {}).toLowerCase();
  const combined = query + ' ' + embeddedText;
  if (/\b(create|shape|design|draft)\s+(a\s+)?(new\s+)?skill\b/i.test(combined) || combined.includes('create_skill')) return 'create_skill';
  if (combined.includes('activate_skill') || combined.includes('run approved skill') || combined.includes('approved skill') || combined.includes('day plan') || combined.includes('project-management-support')) return 'activate_skill';
  if (combined.includes('ingest_or_stage_knowledge') || combined.includes('ingest') || combined.includes('upload') || combined.includes('transcript') || combined.includes('capture knowledge')) return 'ingest_or_stage_knowledge';
  if (combined.includes('retrieve_knowledge') || combined.includes('retrieve') || combined.includes('knowledge graph') || combined.includes('citation') || combined.includes('source document')) return 'retrieve_knowledge';
  return 'answer_direct';
}

function externalWriteIntent(inputValue, embedded) {
  const text = (JSON.stringify(inputValue || {}) + ' ' + JSON.stringify(embedded || {})).toLowerCase();
  return /\b(send|email|mail|invite|schedule|calendar|meeting invite|publish|commit|delete|external write)\b/i.test(text);
}

const embedded = safeJson(ai) || safeJson(aiText) || {};
const embeddedOutput = embedded.output && typeof embedded.output === 'object' ? embedded.output : embedded;
const actorRoute = normalizeDecision(embeddedOutput.route_decision || embedded.route_decision);
const contextRoute = normalizeDecision(input.context?.route_decision || input.output?.route_decision);
const inferredDecision = inferDecision(input, embeddedOutput);
const decision = actorRoute.decision || inferredDecision || contextRoute.decision || 'answer_direct';
const delegationTarget = embedded.delegation?.target || embedded.delegate?.target_agent || null;
const targetAgent = actorRoute.target_agent || delegationTarget || (['retrieve_knowledge','ingest_or_stage_knowledge'].includes(decision) ? 'knowledge_fabric_agent' : ['activate_skill','create_skill'].includes(decision) ? 'agentic_butler' : decision === 'request_human_clarification' ? 'human' : 'actor_twin');
const intent = actorRoute.intent || input.intent || (decision === 'activate_skill' ? 'activate_skill' : decision === 'create_skill' ? 'create_skill' : decision === 'ingest_or_stage_knowledge' ? 'ingest_concept' : decision === 'retrieve_knowledge' ? 'retrieve_context' : decision === 'request_human_clarification' ? 'clarify' : 'answer_question');
const approvalRequired = Boolean(decision === 'create_skill' || decision === 'request_human_clarification' || externalWriteIntent(input, embeddedOutput));

const routeDecision = {
  decision,
  target_agent: targetAgent,
  intent,
  visible_state: actorRoute.visible_state || (decision === 'answer_direct' ? 'answering' : targetAgent === 'knowledge_fabric_agent' ? (decision === 'retrieve_knowledge' ? 'using_knowledge' : 'capturing_knowledge') : targetAgent === 'agentic_butler' ? 'activating_skill' : 'approval_required'),
  approval_required: approvalRequired,
  handoff_required: Boolean(actorRoute.handoff_required ?? (targetAgent !== 'actor_twin' && targetAgent !== 'human')),
  reason: actorRoute.reason || embedded.notes || (actorRoute.decision ? 'Actor Twin AI route decision is authoritative.' : 'Actor Twin route decision inferred with context route as fallback only.')
};

const delegateEnvelope = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: requestId + '_' + routeDecision.target_agent,
  timestamp: new Date().toISOString(),
  agent_id: routeDecision.target_agent,
  intent: routeDecision.intent,
  principal: input.principal || { twin_id: input.twin_id || input.input?.twin_id || 'florian', display_name: input.display_name || 'Florian' },
  input: {
    ...(input.input || {}),
    query: input.input?.query || input.input?.message || input.chatInput || input.message || '',
    skill_id: input.input?.skill_id || embedded.skill?.name || embedded.skill_id || undefined,
    actor_answer_candidate: embeddedOutput.answer || embedded.answer || aiText
  },
  context: { ...(input.context || {}), called_by: 'actor_twin', route_decision: routeDecision, orchestration_model: 'uat_n8n_direct' },
  approval: { required: false, reason: 'Delegated by Actor Twin route decision. Human approval is only required for new skill creation or external write actions.' }
};

return [{ json: {
  input,
  ai_text: aiText,
  request_id: requestId,
  route_decision: routeDecision,
  delegate_envelope: delegateEnvelope,
  actor_answer_candidate: embeddedOutput.answer || embedded.answer || aiText
} }];

const current = $json;
const normalized = current.route_decision ? current : $('Normalize route decision').first().json;
const delegate = current.agent_id && current.agent_id !== 'actor_twin' ? current : null;
const route = normalized.route_decision;
const delegateApproval = delegate?.approval || {};
const delegateOutput = delegate?.output || {};
const proposed = JSON.stringify({ approval: delegateApproval, output: delegateOutput }).toLowerCase();
const externalWrite = /\b(send|email|mail|invite|schedule|calendar|meeting invite|publish|commit|delete|external write)\b/i.test(proposed);
const approvalRequired = Boolean(route.decision === 'create_skill' || route.decision === 'request_human_clarification' || delegateApproval.gate === 'skill_spec_approval' || externalWrite);
const finalRoute = { ...route, approval_required: approvalRequired };
return [{ json: {
  envelope_version: normalized.input?.envelope_version || '0.1.0',
  request_id: normalized.request_id,
  agent_id: 'actor_twin',
  status: approvalRequired ? 'approval_required' : 'completed',
  output: {
    answer: delegate?.output?.answer || delegate?.output?.summary || normalized.actor_answer_candidate || 'Actor Twin completed orchestration.',
    route_decision: finalRoute,
    delegate_result: delegate,
    confidence: delegate?.output?.confidence || 0.78,
    citations: delegate?.output?.citations || [],
    actor_review: delegate ? 'Actor Twin delegated autonomous worker execution, then shaped the final response boundary.' : 'Actor Twin answered directly.'
  },
  approval: approvalRequired ? (delegateApproval.required ? delegateApproval : { required: true, gate: finalRoute.intent, summary: finalRoute.reason, proposed_action: 'Human review required before continuing.' }) : { required: false },
  trace: {
    stored: true,
    trace_id: 'n8n_actor_orchestration_' + Date.now(),
    orchestration_model: 'uat_n8n_direct',
    used_agents: ['actor_twin'].concat(finalRoute.target_agent && !['actor_twin','human'].includes(finalRoute.target_agent) ? [finalRoute.target_agent] : []),
    route_decision: finalRoute.decision,
    target_agent: finalRoute.target_agent,
    delegate_trace_id: delegate?.trace?.trace_id || '',
    handoff_status: delegate ? 'delegated_autonomous' : 'not_required'
  }
} }];
